/** A tag as genres compare: no case, accents, spaces or punctuation, "&" as
 * "and". "Post-Rock", "post rock" and "postrock" are the same tag. */
export function normTag(tag: string): string {
  return tag
    .normalize("NFD")
    .replace(/\p{M}/gu, "")
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]/g, "");
}

export function getPipGenre(key: string): PipGenre | undefined {
  return PIP_GENRES.find((g) => g.key === key);
}

/** Whether any of `tags` names the genre. Whole tags only: "dubstep" isn't
 * "dub". */
export function genreInTags(genre: PipGenre, tags: Iterable<string>): boolean {
  const wanted = new Set(
    [genre.name, genre.key, ...(genre.tags ?? [])].map(normTag),
  );
  for (const t of tags) if (wanted.has(normTag(t))) return true;
  return false;
}
